/// A stage of a job that is not plain work towards its percent.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum JobPhase {
    Unspecified = 0,
    /// FFmpeg wrote the last frame and is rewriting the output, such as moving
    /// an MP4's index to the front for fast start, or rclone sent every byte and
    /// waits for the destination to confirm the files in flight.
    Finalizing = 1,
    /// The processor waits to try its work again after a failed attempt, such
    /// as an rclone or BaiduPCS-Go upload.
    Retrying = 2,
    /// An upload prepares its files before sending them: none of the files it is
    /// working on has sent data yet. Before sending a file BaiduPCS-Go checks the
    /// Netdisk and hashes the file without progress output, and rclone may hash
    /// it for the destination; before its first transfer rclone lists the
    /// destination and compares the files already there.
    Preparing = 3,
}
